insert into public.courses(id,program_id,name,slug,description,category,learner_stage,skill_type,estimated_hours,context_tags) values
('d1000000-0000-4000-8000-000000000001','e1d3ba49-ab27-4664-be12-93794b5ac2e3','SMP: Siap Masuk SMA/SMK Pilihan','smp-siap-masuk-sma-smk','Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.','Persiapan Pendidikan','SMP / Kelas IX','mixed',8,'["SMP","SPMB","belajar","mental"]'::jsonb),
('d1000000-0000-4000-8000-000000000002','66e4c5e9-7610-46c1-9e78-22ad94e447bd','SMP: Belajar Efektif, Disiplin Diri, dan Karakter','smp-belajar-efektif-karakter','Kebiasaan belajar, tanggung jawab, fokus, pengelolaan gawai, komunikasi, dan keberanian meminta bantuan.','Soft Skills & Karakter','SMP','soft_skill',6,'["SMP","karakter","disiplin"]'::jsonb),
('d1000000-0000-4000-8000-000000000003','851010a9-b031-47d0-a594-b4c47adc7224','SMA/SMK: Siap Menghadapi Dunia Kerja Pertama','sma-smk-siap-kerja-pertama','Lowongan aman, CV, wawancara, komunikasi kerja, disiplin, hak dasar pekerja, dan kewaspadaan terhadap lowongan palsu.','Karier & Dunia Kerja','SMA / SMK / Lulusan','mixed',10,'["SMA","SMK","CV","kerja"]'::jsonb),
('d1000000-0000-4000-8000-000000000004','851010a9-b031-47d0-a594-b4c47adc7224','SMA/SMK: Menentukan Jalur Setelah Lulus','sma-smk-rencana-setelah-lulus','Membandingkan kuliah, pendidikan vokasi, pelatihan, kerja, magang, dan usaha tanpa stigma; keputusan berbasis kondisi nyata.','Karier & Dunia Kerja','SMA / SMK / Kelas XII / Lulusan','soft_skill',5,'["SMA","SMK","kuliah","vokasi","kerja"]'::jsonb),
('d1000000-0000-4000-8000-000000000005','66e4c5e9-7610-46c1-9e78-22ad94e447bd','Wirausaha Mikro dari Nol: Usaha Lokal yang Teruji','wirausaha-mikro-dari-nol','Menguji usaha kecil Indonesia—makanan, jasa, kerajinan, reseller, pertanian, layanan digital—dimulai dari pelanggan dan hitungan biaya.','Wirausaha & UMKM','SMA / SMK / Dewasa','mixed',12,'["UMKM","usaha","arus kas"]'::jsonb),
('d1000000-0000-4000-8000-000000000006','7a021b82-3828-4e9a-a2ef-f94e0845d5c7','IT: Produktivitas Digital dan Literasi AI','it-produktivitas-digital-ai','Keterampilan komputer, dokumen, spreadsheet, kolaborasi, AI, verifikasi informasi, dan keamanan data.','IT & Teknologi','SMP akhir / SMA / SMK / Dewasa','hard_skill',8,'["IT","komputer","AI","spreadsheet"]'::jsonb),
('d1000000-0000-4000-8000-000000000007','7a021b82-3828-4e9a-a2ef-f94e0845d5c7','IT: Dasar Pemrograman Web dan Portofolio','it-web-development-portofolio','HTML, CSS, JavaScript dasar, aksesibilitas, debugging, Git, dan proyek web kecil untuk portofolio.','IT & Teknologi','SMA / SMK / Mahasiswa / Pemula','hard_skill',14,'["IT","coding","web"]'::jsonb),
('d1000000-0000-4000-8000-000000000008','7a021b82-3828-4e9a-a2ef-f94e0845d5c7','Digital Marketing untuk UMKM dan Usaha Lokal','digital-marketing-umkm','Katalog, konten, foto produk, pesan promosi, layanan pelanggan, dan evaluasi sederhana untuk usaha kecil.','IT & Teknologi','SMA / SMK / Dewasa','mixed',10,'["digital marketing","UMKM","konten"]'::jsonb),
('d1000000-0000-4000-8000-000000000009','66e4c5e9-7610-46c1-9e78-22ad94e447bd','Literasi Keuangan, Anggaran, dan Anti-Penipuan','literasi-keuangan-anti-penipuan','Anggaran uang saku atau pendapatan, biaya pinjaman, penipuan investasi/digital, dan keputusan berhati-hati.','Keuangan & Kemandirian','SMP akhir / SMA / SMK / Dewasa','mixed',7,'["keuangan","utang","penipuan"]'::jsonb),
('d1000000-0000-4000-8000-000000000010','66e4c5e9-7610-46c1-9e78-22ad94e447bd','Soft Skills: Komunikasi, Resiliensi, dan Konflik','softskill-komunikasi-resiliensi','Komunikasi asertif, mendengar aktif, menerima kritik, mengelola konflik, kerja kelompok, dan meminta dukungan.','Soft Skills & Karakter','SMP / SMA / SMK / Mahasiswa / Dewasa','soft_skill',7,'["komunikasi","resiliensi","konflik"]'::jsonb),
('d1000000-0000-4000-8000-000000000011','851010a9-b031-47d0-a594-b4c47adc7224','Vokasi: Layanan Pelanggan, SOP, dan Keselamatan Kerja','vokasi-layanan-sop-k3','Keterampilan dasar ritel, layanan, perhotelan, bengkel, dapur, dan administrasi: SOP, layanan pelanggan, kebersihan, pencatatan, keselamatan.','Vokasi & Layanan Profesional','SMA / SMK / Lulusan','hard_skill',10,'["vokasi","SMK","SOP","K3"]'::jsonb),
('d1000000-0000-4000-8000-000000000012','7a021b82-3828-4e9a-a2ef-f94e0845d5c7','Literasi Digital: Anti-Hoaks, Privasi, dan Keamanan Akun','literasi-digital-anti-hoaks','Situasi sehari-hari: pesan berantai, tautan hadiah, penipuan WhatsApp, akun dibajak, dan informasi viral.','IT & Teknologi','SMP / SMA / SMK / Mahasiswa / Dewasa','hard_skill',6,'["keamanan digital","hoaks","privasi"]'::jsonb),
('d1000000-0000-4000-8000-000000000013','7a021b82-3828-4e9a-a2ef-f94e0845d5c7','IT Perkantoran: Spreadsheet, Data, dan Administrasi','it-spreadsheet-administrasi','Spreadsheet, data rapi, surat, laporan, dan arsip untuk sekolah, toko, kantor kecil, organisasi, dan usaha keluarga.','IT & Teknologi','SMA / SMK / Lulusan / Dewasa','hard_skill',8,'["spreadsheet","administrasi","data"]'::jsonb),
('d1000000-0000-4000-8000-000000000014','66e4c5e9-7610-46c1-9e78-22ad94e447bd','Hard Skills: Matematika Praktis dan Pemecahan Masalah','hard-skill-matematika-praktis','Persen, perbandingan, estimasi, membaca grafik, ukuran, dan logika untuk belanja, usaha, perjalanan, dan proyek.','Hard Skills & Kecakapan Hidup','SMP / SMA / SMK / Mahasiswa / Dewasa','hard_skill',6,'["matematika","problem solving","SMP"]'::jsonb)
