insert into public.lessons(id,module_id,title,content,position) values
('d3000000-0000-4000-8000-000000000001','d2000000-0000-4000-8000-000000000001','Mengenali stres ujian dan meminta dukungan','{"sources":[{"url":"https://github.com/akvisomr-eng/EDUNEXUS-SOFTSKILL-HARDSKILL-/blob/main/docs/EDUNEXUS-KNOWLEDGE-CURRICULUM-REGISTRY-v1.0.md","note":"Materi orisinal EDUNEXUS. Buka registri untuk rujukan eksternal dan standar provenance.","title":"Registri Kurikulum EDUNEXUS"}],"summary":"Mengenali stres ujian dan meminta dukungan. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","exercise":"Latihan: Mengenali stres ujian dan meminta dukungan. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama. Buat satu contoh nyata atau simulasi, jelaskan langkah, risiko, dan indikator keberhasilan.","sections":[{"body":"Mulai dari situasi nyata, pisahkan fakta dari asumsi, identifikasi batasan, pilih langkah kecil yang bisa diuji, lalu catat hasil dan hal yang perlu diverifikasi.","heading":"Langkah belajar"},{"body":"Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","heading":"Konteks dan kehati-hatian"}],"objectives":["Memahami konsep dan istilah utama terkait mengenali stres ujian dan meminta dukungan.","Menerapkan langkah yang aman, realistis, dan sesuai konteks Indonesia.","Menjelaskan alasan keputusan, bukti, dan batasan yang belum diketahui."],"license_note":"Materi latihan orisinal EDUNEXUS. Verifikasi aturan resmi terbaru untuk urusan pendidikan, ketenagakerjaan, keselamatan, atau keuangan."}'::jsonb,1),
('d3000000-0000-4000-8000-000000000002','d2000000-0000-4000-8000-000000000001','Target realistis dan pola pikir berkembang','{"sources":[{"url":"https://github.com/akvisomr-eng/EDUNEXUS-SOFTSKILL-HARDSKILL-/blob/main/docs/EDUNEXUS-KNOWLEDGE-CURRICULUM-REGISTRY-v1.0.md","note":"Materi orisinal EDUNEXUS. Buka registri untuk rujukan eksternal dan standar provenance.","title":"Registri Kurikulum EDUNEXUS"}],"summary":"Target realistis dan pola pikir berkembang. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","exercise":"Latihan: Target realistis dan pola pikir berkembang. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama. Buat satu contoh nyata atau simulasi, jelaskan langkah, risiko, dan indikator keberhasilan.","sections":[{"body":"Mulai dari situasi nyata, pisahkan fakta dari asumsi, identifikasi batasan, pilih langkah kecil yang bisa diuji, lalu catat hasil dan hal yang perlu diverifikasi.","heading":"Langkah belajar"},{"body":"Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","heading":"Konteks dan kehati-hatian"}],"objectives":["Memahami konsep dan istilah utama terkait target realistis dan pola pikir berkembang.","Menerapkan langkah yang aman, realistis, dan sesuai konteks Indonesia.","Menjelaskan alasan keputusan, bukti, dan batasan yang belum diketahui."],"license_note":"Materi latihan orisinal EDUNEXUS. Verifikasi aturan resmi terbaru untuk urusan pendidikan, ketenagakerjaan, keselamatan, atau keuangan."}'::jsonb,2),
('d3000000-0000-4000-8000-000000000003','d2000000-0000-4000-8000-000000000002','Jadwal belajar dan latihan bertahap','{"sources":[{"url":"https://github.com/akvisomr-eng/EDUNEXUS-SOFTSKILL-HARDSKILL-/blob/main/docs/EDUNEXUS-KNOWLEDGE-CURRICULUM-REGISTRY-v1.0.md","note":"Materi orisinal EDUNEXUS. Buka registri untuk rujukan eksternal dan standar provenance.","title":"Registri Kurikulum EDUNEXUS"}],"summary":"Jadwal belajar dan latihan bertahap. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","exercise":"Latihan: Jadwal belajar dan latihan bertahap. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama. Buat satu contoh nyata atau simulasi, jelaskan langkah, risiko, dan indikator keberhasilan.","sections":[{"body":"Mulai dari situasi nyata, pisahkan fakta dari asumsi, identifikasi batasan, pilih langkah kecil yang bisa diuji, lalu catat hasil dan hal yang perlu diverifikasi.","heading":"Langkah belajar"},{"body":"Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","heading":"Konteks dan kehati-hatian"}],"objectives":["Memahami konsep dan istilah utama terkait jadwal belajar dan latihan bertahap.","Menerapkan langkah yang aman, realistis, dan sesuai konteks Indonesia.","Menjelaskan alasan keputusan, bukti, dan batasan yang belum diketahui."],"license_note":"Materi latihan orisinal EDUNEXUS. Verifikasi aturan resmi terbaru untuk urusan pendidikan, ketenagakerjaan, keselamatan, atau keuangan."}'::jsonb,1),
('d3000000-0000-4000-8000-000000000004','d2000000-0000-4000-8000-000000000002','Menganalisis kesalahan tanpa panik','{"sources":[{"url":"https://github.com/akvisomr-eng/EDUNEXUS-SOFTSKILL-HARDSKILL-/blob/main/docs/EDUNEXUS-KNOWLEDGE-CURRICULUM-REGISTRY-v1.0.md","note":"Materi orisinal EDUNEXUS. Buka registri untuk rujukan eksternal dan standar provenance.","title":"Registri Kurikulum EDUNEXUS"}],"summary":"Menganalisis kesalahan tanpa panik. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","exercise":"Latihan: Menganalisis kesalahan tanpa panik. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama. Buat satu contoh nyata atau simulasi, jelaskan langkah, risiko, dan indikator keberhasilan.","sections":[{"body":"Mulai dari situasi nyata, pisahkan fakta dari asumsi, identifikasi batasan, pilih langkah kecil yang bisa diuji, lalu catat hasil dan hal yang perlu diverifikasi.","heading":"Langkah belajar"},{"body":"Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","heading":"Konteks dan kehati-hatian"}],"objectives":["Memahami konsep dan istilah utama terkait menganalisis kesalahan tanpa panik.","Menerapkan langkah yang aman, realistis, dan sesuai konteks Indonesia.","Menjelaskan alasan keputusan, bukti, dan batasan yang belum diketahui."],"license_note":"Materi latihan orisinal EDUNEXUS. Verifikasi aturan resmi terbaru untuk urusan pendidikan, ketenagakerjaan, keselamatan, atau keuangan."}'::jsonb,2),
('d3000000-0000-4000-8000-000000000005','d2000000-0000-4000-8000-000000000003','Memahami jalur dan aturan daerah','{"sources":[{"url":"https://pdm.kemendikdasmen.go.id/spmb","note":"Periksa juga petunjuk teknis pemerintah daerah. Jalur dan mekanisme seleksi dapat berbeda.","title":"SPMB Kemendikdasmen Tahun 2026"},{"url":"https://github.com/akvisomr-eng/EDUNEXUS-SOFTSKILL-HARDSKILL-/blob/main/docs/EDUNEXUS-KNOWLEDGE-CURRICULUM-REGISTRY-v1.0.md","note":"Materi orisinal EDUNEXUS. Buka registri untuk rujukan eksternal dan standar provenance.","title":"Registri Kurikulum EDUNEXUS"}],"summary":"Memahami jalur dan aturan daerah. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","exercise":"Latihan: Memahami jalur dan aturan daerah. Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama. Buat satu contoh nyata atau simulasi, jelaskan langkah, risiko, dan indikator keberhasilan.","sections":[{"body":"Mulai dari situasi nyata, pisahkan fakta dari asumsi, identifikasi batasan, pilih langkah kecil yang bisa diuji, lalu catat hasil dan hal yang perlu diverifikasi.","heading":"Langkah belajar"},{"body":"Persiapan mental, kebiasaan belajar, pemetaan pilihan sekolah, dokumen, dan strategi menghadapi SPMB sesuai aturan daerah. Tidak menjanjikan kelulusan atau menganggap semua sekolah memakai tes yang sama.","heading":"Konteks dan kehati-hatian"}],"objectives":["Memahami konsep dan istilah utama terkait memahami jalur dan aturan daerah.","Menerapkan langkah yang aman, realistis, dan sesuai konteks Indonesia.","Menjelaskan alasan keputusan, bukti, dan batasan yang belum diketahui."],"license_note":"Materi latihan orisinal EDUNEXUS. Verifikasi aturan resmi terbaru untuk urusan pendidikan, ketenagakerjaan, keselamatan, atau keuangan."}'::jsonb,1),
