-- EDUNEXUS Indonesia-focused course catalog seed; safe to re-run.
alter table public.courses add column if not exists category text not null default 'Umum';
alter table public.courses add column if not exists learner_stage text not null default 'Semua jenjang';
alter table public.courses add column if not exists skill_type text not null default 'mixed';
alter table public.courses add column if not exists estimated_hours integer not null default 4;
alter table public.courses add column if not exists context_tags jsonb not null default '[]'::jsonb;

update public.courses set category=case when name ilike '%AI%' or name ilike '%digital%' or name ilike '%data%' or name ilike '%keamanan%' then 'IT & Teknologi' when name ilike '%karier%' or name ilike '%kerja%' or name ilike '%portofolio%' then 'Karier & Dunia Kerja' when name ilike '%komunikasi%' or name ilike '%belajar%' or name ilike '%metakognisi%' then 'Soft Skills & Karakter' else 'Pengembangan Umum' end where category='Umum';

update public.courses set learner_stage=case when name ilike '%SMP%' then 'SMP / SMA / SMK / Mahasiswa / Dewasa' else 'SMP / SMA / SMK / Mahasiswa / Dewasa' end where learner_stage='Semua jenjang';

update public.courses set skill_type=case when category='IT & Teknologi' then 'hard_skill' when category='Soft Skills & Karakter' then 'soft_skill' else 'mixed' end where skill_type='mixed' and category in ('IT & Teknologi','Soft Skills & Karakter');

on conflict(slug) do update set name=excluded.name,description=excluded.description,category=excluded.category,learner_stage=excluded.learner_stage,skill_type=excluded.skill_type,estimated_hours=excluded.estimated_hours,context_tags=excluded.context_tags,updated_at=now();

on conflict(id) do update set course_id=excluded.course_id,name=excluded.name,position=excluded.position;

on conflict(id) do update set module_id=excluded.module_id,title=excluded.title,content=excluded.content,position=excluded.position;
